let worklogCache: WorklogRow[] | null = null;
export function mockWorklog(now = Date.now()): WorklogRow[] {
  if (worklogCache) return worklogCache;
  const today = new Date(now);
  today.setHours(0, 0, 0, 0);
  const pad = (n: number) => String(n).padStart(2, '0');
  worklogCache = MOCK_STINTS.map(([ago, h, m, wall, active, idx], i) => {
    const it = MOCK_ITEMS[idx];
    const start = new Date(today);
    start.setDate(start.getDate() - ago);
    start.setHours(h, m, 0, 0);
    const end = new Date(start.getTime() + wall * 60_000);
    return {
      id: `wl-${i + 1}`,
      host: it.host,
      editor: it.editor,
      kind: it.kind,
      course_key: it.course_key,
      course_label: it.course_label,
      item_key: it.item_key,
      item_label: it.item_label,
      doc: it.doc ?? null,
      start: start.toISOString(),
      end: end.toISOString(),
      active_ms: active * 60_000,
      day: `${start.getFullYear()}-${pad(start.getMonth() + 1)}-${pad(start.getDate())}`,
      heartbeats: Math.round((active * 60) / 15),
    };
  });
  return worklogCache;
}
